package com.aistock.market.alert;
import com.aistock.market.calendar.*;import com.aistock.market.quotation.*;import com.aistock.market.version.MarketVersionRepository;import com.aistock.common.BusinessException;
import java.time.*;import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AlertBoundaryCalendarTest {
 @Test void independentCalendarExtendsRawAcrossWeekendAfterCutoff(){var repo=mock(MarketVersionRepository.class);var jdbc=mock(JdbcTemplate.class);when(repo.jdbc()).thenReturn(jdbc);var version=UUID.randomUUID();when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("version_id",version.toString())));var p=new BigDecimal("25");when(repo.bars(version.toString())).thenReturn(List.of(new RawBar(LocalDate.of(2026,10,9),p,p,p,p,p,p,1,null)));when(repo.calendar(version.toString())).thenReturn(List.of(new TradingDay(LocalDate.of(2026,10,9),true)));var calendar=mock(CalendarService.class);var days=List.of(new CalendarRecords.Day(LocalDate.of(2026,10,9),true),new CalendarRecords.Day(LocalDate.of(2026,10,10),false),new CalendarRecords.Day(LocalDate.of(2026,10,11),false));var clock=Clock.fixed(Instant.parse("2026-10-11T13:00:00Z"),ZoneOffset.UTC);var snapshot=new CalendarRecords.Snapshot(UUID.randomUUID(),new CalendarRecords.Candidate("baostock",days.get(0).date(),days.get(2).date(),clock.instant(),CalendarService.hash(days),days));when(calendar.covering(any(),any())).thenReturn(Optional.of(snapshot));var service=new AlertBoundaryService(repo,calendar,clock,20);assertEquals(LocalDate.of(2026,10,9),service.get("SH600030").effectiveAfterTradeDate());when(calendar.covering(any(),any())).thenReturn(Optional.empty());assertThrows(BusinessException.class,()->service.get("SH600030"));}
}
